CREATE TABLE [sales].[SalesDiscounts]([SalesDiscountId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SalesDiscounts_Id] DEFAULT NEWSEQUENTIALID(),[InvoiceId] UNIQUEIDENTIFIER NOT NULL,[InvoiceItemId] UNIQUEIDENTIFIER NULL,[DiscountType] NVARCHAR(20) NOT NULL,[DiscountMode] NVARCHAR(20) NOT NULL,[DiscountValue] DECIMAL(18,4) NOT NULL,[DiscountAmount] DECIMAL(18,2) NOT NULL,[AuthorizedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SalesDiscounts_Created] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_SalesDiscounts] PRIMARY KEY([SalesDiscountId]),CONSTRAINT [FK_SalesDiscounts_Invoice] FOREIGN KEY([InvoiceId]) REFERENCES [sales].[SalesInvoices]([InvoiceId]) ON DELETE CASCADE,CONSTRAINT [FK_SalesDiscounts_Item] FOREIGN KEY([InvoiceItemId]) REFERENCES [sales].[SalesInvoiceItems]([InvoiceItemId]),CONSTRAINT [CK_SalesDiscounts_Type] CHECK([DiscountType] IN('ITEM','BILL')),CONSTRAINT [CK_SalesDiscounts_Mode] CHECK([DiscountMode] IN('PERCENTAGE','FLAT')));
